  let parameterLinks = {};
  async function openParameterLink(id, index = 0, docs = false) {
    try {
      const response = await call(robotPath('/omnifleet_t2/nav2/save_parameters'), {parameters:[{
        name:docs ? '__open_docs' : '__open_config',
        value:{type:4,string_value:JSON.stringify({id,index})}
      }]});
      if (!response.results?.[0]?.successful) throw new Error(response.results?.[0]?.reason || '无法打开链接');
      setStatus((docs ? '已打开官方说明：' : '已打开配置位置：') + response.results[0].reason, 'ok');
    } catch(error) {setStatus('打开失败：' + String(error), 'error');}
  }
  function configAnchor(id, label, index=0) {
    const a=document.createElement('a'); a.href='#'; a.textContent=label;
    a.dataset.configParameter=id; a.dataset.configIndex=String(index);
    const target=parameterLinks[id]?.targets?.[index];
    if(target){a.href='file://'+target.path+'#L'+target.line; a.title=target.path+':'+target.line+':'+target.column+' · '+target.label;}
    a.onclick=e=>{e.preventDefault();openParameterLink(id,index);};
    return a;
  }
  function updateParameterLinks() {
    for (const a of root.querySelectorAll('[data-config-parameter]')) {
      const target=parameterLinks[a.dataset.configParameter]?.targets?.[Number(a.dataset.configIndex)];
      if(target){a.href='file://'+target.path+'#L'+target.line; a.title=target.path+':'+target.line+':'+target.column+' · '+target.label;}
    }
    for(const a of root.querySelectorAll('[data-doc-parameter]')) {
      const docs=parameterLinks[a.dataset.docParameter]?.docs;
      if(docs){a.href=docs.url; a.title=docs.note;}
    }
    for(const label of root.querySelectorAll('[data-parameter-label]')) {
      const id=label.dataset.parameterLabel, targets=parameterLinks[id]?.targets || [];
      if(targets.length<2 || label.querySelector('.additional-config-links'))continue;
      const extra=document.createElement('span');extra.className='additional-config-links';
      targets.slice(1).forEach((target,i)=>{extra.append(' · ', configAnchor(id,target.label,i+1));});
      label.append(extra);
    }
  }
  function appendParameterHelp(title, id) {
    const name=title.textContent; title.textContent='';title.dataset.parameterLabel=id;
    const link = configAnchor(id, name);
    const separator = name.indexOf(' · ');
    if (separator >= 0) {
      const chinese = document.createElement('span'); chinese.className = 'parameter-title-cn'; chinese.textContent = name.slice(0, separator);
      const english = document.createElement('span'); english.className = 'parameter-title-en'; english.textContent = name.slice(separator + 3);
      link.textContent = ''; link.append(chinese, ' · ', english);
    }
    title.append(link);
    const reference = document.createElement('small'); reference.className = 'parameter-reference';
    reference.textContent = '参考值：' + parameterReferences[id];
    const text = document.createElement('small'); text.className = 'parameter-help';
    const explanation=document.createElement('a');explanation.textContent='说明';explanation.href='#';
    explanation.dataset.docParameter=id;
    explanation.onclick=e=>{e.preventDefault();openParameterLink(id,0,true);};
    text.append(explanation, '：'+parameterHelp[id]); title.append(reference, text);
  }
